# Test input with explicit values
test_input = [
    [9]*8 + [4] + [9]*8 + [4] + [9]*8,  # row 0: 9 9...4 9...4 9...
    [9]*8 + [4] + [9]*8 + [4] + [9]*8,  # row 1: same
    [4] * 26,  # row 2: all 4s (horizontal separator)
    [9]*8 + [4] + [8, 9, 8, 9, 6, 9, 8, 7] + [4] + [9]*8,  # row 3: has 8s and 7s
    [9]*8 + [4] + [9, 9, 9, 8, 8, 3, 9, 9] + [4] + [9]*8,  # row 4: has 8,8,3
]

# Compute merged row-by-row
merged_output = []
for r in range(5):
    if r == 2:
        merged_output.append([4] * 26)
    else:
        top_row = test_input[r]
        bot_row = test_input[4 - r]  # mirror: 0<->4, 1<->3
        merged_row = []
        for c in range(26):
            v1, v2 = top_row[c], bot_row[c]
            if v1 != 9:
                merged_row.append(v1)
            elif v2 != 9:
                merged_row.append(v2)
            else:
                merged_row.append(9)
        merged_output.append(merged_row)

print("Merged output:")
for i, row in enumerate(merged_output):
    print(f"Row {i}: {row}")

